/**
 * Pakistan School Seeb - Core Interactions
 */
(function () {
  'use strict';

  window.PSS_PRINT_LOGO = 'data:image/png;base64,';
  window.PSS_SCHOOL_EMAIL = '';


  // ===== Theme Toggle =====
  const themeToggle = document.getElementById('theme-toggle');
  const root = document.documentElement;
  const savedTheme = localStorage.getItem('pss-theme') || 'light';
  root.setAttribute('data-theme', savedTheme);

  function updateThemeIcon() {
    if (!themeToggle) return;
    const isDark = root.getAttribute('data-theme') === 'dark';
    themeToggle.innerHTML = isDark
      ? '<svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>'
      : '<svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>';
  }
  updateThemeIcon();

  if (themeToggle) {
    themeToggle.addEventListener('click', () => {
      const next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      localStorage.setItem('pss-theme', next);
      updateThemeIcon();
    });
  }

  // ===== Mobile Menu =====
  const menuToggle = document.getElementById('menu-toggle');
  const mobileNav = document.getElementById('mobile-nav');
  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', () => {
      mobileNav.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', mobileNav.classList.contains('open'));
    });
    mobileNav.querySelectorAll('a').forEach(a => {
      a.addEventListener('click', () => mobileNav.classList.remove('open'));
    });
  }

  // ===== Navbar scroll =====
  const navbar = document.querySelector('.navbar');
  if (navbar) {
    window.addEventListener('scroll', () => {
      navbar.classList.toggle('scrolled', window.scrollY > 40);
    }, { passive: true });
  }

  // ===== Tabs =====
  document.querySelectorAll('[data-tabs]').forEach(container => {
    const buttons = container.querySelectorAll('.tab-btn');
    const panels = container.querySelectorAll('.tab-panel');
    buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.dataset.tab;
        buttons.forEach(b => b.classList.remove('active'));
        panels.forEach(p => p.classList.remove('active'));
        btn.classList.add('active');
        const panel = container.querySelector(`[data-panel="${target}"]`);
        if (panel) panel.classList.add('active');
      });
    });
  });

  // ===== Noticeboard Filter =====
  const noticeSearch = document.getElementById('notice-search');
  const noticeChips = document.querySelectorAll('.filter-chips .chip');
  const noticeItems = document.querySelectorAll('.notice-item');
  let activeCategory = 'all';

  function filterNotices() {
    const q = (noticeSearch?.value || '').toLowerCase().trim();
    noticeItems.forEach(item => {
      const cat = item.dataset.category || '';
      const text = item.textContent.toLowerCase();
      const matchCat = activeCategory === 'all' || cat === activeCategory;
      const matchQ = !q || text.includes(q);
      item.style.display = matchCat && matchQ ? '' : 'none';
    });
  }

  if (noticeSearch) noticeSearch.addEventListener('input', filterNotices);
  noticeChips.forEach(chip => {
    chip.addEventListener('click', () => {
      noticeChips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      activeCategory = chip.dataset.filter || 'all';
      filterNotices();
    });
  });

  // ===== Testimonial Slider =====
  const track = document.querySelector('.testimonial-track');
  const dots = document.querySelectorAll('.slider-dots .dot');
  let currentSlide = 0;
  if (track && dots.length) {
    function goToSlide(i) {
      currentSlide = i;
      track.style.transform = `translateX(-${i * 100}%)`;
      dots.forEach((d, idx) => d.classList.toggle('active', idx === i));
    }
    dots.forEach((dot, i) => dot.addEventListener('click', () => goToSlide(i)));
    setInterval(() => goToSlide((currentSlide + 1) % dots.length), 6000);
  }

  // ===== Gallery Filter & Lightbox =====
  const galleryFilters = document.querySelectorAll('.gallery-filters .chip');
  const galleryItems = document.querySelectorAll('.gallery-item');
  galleryFilters.forEach(chip => {
    chip.addEventListener('click', () => {
      galleryFilters.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      const filter = chip.dataset.filter || 'all';
      galleryItems.forEach(item => {
        const cat = item.dataset.category || '';
        item.style.display = filter === 'all' || cat === filter ? '' : 'none';
      });
    });
  });

  const lightbox = document.getElementById('lightbox');
  const lightboxContent = document.querySelector('.lightbox-content');
  galleryItems.forEach(item => {
    item.addEventListener('click', () => {
      if (!lightbox) return;
      const title = item.dataset.title || '';
      const emoji = '';
      lightboxContent.innerHTML = `
        <div class="placeholder" style="display:flex;align-items:center;justify-content:center"><svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg></div>
        <h3 style="color:white;margin-bottom:0.5rem">${title}</h3>
        <p style="color:rgba(255,255,255,0.7)">${item.dataset.date || ''}</p>
      `;
      lightbox.classList.add('open');
      document.body.style.overflow = 'hidden';
    });
  });
  if (lightbox) {
    lightbox.querySelector('.lightbox-close')?.addEventListener('click', closeLightbox);
    lightbox.addEventListener('click', e => { if (e.target === lightbox) closeLightbox(); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape') closeLightbox(); });
  }
  function closeLightbox() {
    lightbox?.classList.remove('open');
    document.body.style.overflow = '';
  }

  // ===== Quick Portal Modal =====
  const portalBtn = document.getElementById('portal-btn');
  const portalModal = document.getElementById('portal-modal');
  if (portalBtn && portalModal) {
    portalBtn.addEventListener('click', () => {
      portalModal.classList.add('open');
      document.body.style.overflow = 'hidden';
    });
    portalModal.querySelector('.modal-close')?.addEventListener('click', () => {
      portalModal.classList.remove('open');
      document.body.style.overflow = '';
    });
    portalModal.addEventListener('click', e => {
      if (e.target === portalModal) {
        portalModal.classList.remove('open');
        document.body.style.overflow = '';
      }
    });
  }

  // ===== Principal Video Modal =====
  const videoBtn = document.getElementById('principal-video-btn');
  const videoModal = document.getElementById('video-modal');
  if (videoBtn && videoModal) {
    videoBtn.addEventListener('click', () => {
      videoModal.classList.add('open');
      document.body.style.overflow = 'hidden';
    });
    videoModal.querySelector('.modal-close')?.addEventListener('click', closeVideo);
    videoModal.addEventListener('click', e => { if (e.target === videoModal) closeVideo(); });
  }
  function closeVideo() {
    videoModal?.classList.remove('open');
    document.body.style.overflow = '';
  }

  // ===== Toast =====
  window.showToast = function (msg, duration = 4000) {
    let toast = document.querySelector('.toast');
    if (!toast) {
      toast = document.createElement('div');
      toast.className = 'toast';
      document.body.appendChild(toast);
    }
    toast.textContent = msg;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), duration);
  };


  // ===== Contact Form (ticket ID + receipt) =====
  const contactForm = document.getElementById('contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', function (e) {
      e.preventDefault();
      e.stopPropagation();

      const name = contactForm.querySelector('[name="name"]');
      const email = contactForm.querySelector('[name="email"]');
      const phone = contactForm.querySelector('[name="phone"]');
      const subject = contactForm.querySelector('[name="subject"]');
      const message = contactForm.querySelector('[name="message"]');
      const submitBtn = document.getElementById('contact-submit-btn') || contactForm.querySelector('[type="submit"]');

      let valid = true;
      [name, email, message].forEach(function (f) {
        if (!f || !String(f.value || '').trim()) {
          if (f) f.classList.add('error');
          valid = false;
        } else if (f) f.classList.remove('error');
      });
      if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())) {
        email.classList.add('error');
        valid = false;
      }
      if (!valid) {
        if (window.showToast) showToast('Please fill in name, email, and message.');
        return;
      }

      // Honeypot
      const hp = contactForm.querySelector('[name="website"]');
      if (hp && hp.value.trim()) {
        contactForm.reset();
        return;
      }

      const inqId =
        'INQ-' +
        Date.now().toString(36).toUpperCase() +
        '-' +
        Math.random().toString(36).slice(2, 6).toUpperCase();

      const inquiry = {
        id: inqId,
        trackingId: inqId,
        name: name.value.trim().slice(0, 120),
        email: email.value.trim().slice(0, 120),
        phone: phone ? phone.value.trim().slice(0, 40) : '',
        subject: subject ? subject.value : 'general',
        message: message.value.trim().slice(0, 5000),
        status: 'new',
        note: '',
        publicNotes: '',
        createdAt: new Date().toISOString()
      };

      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Submitting…';
      }

      function saveLocal(row) {
        try {
          const list = JSON.parse(localStorage.getItem('pss-inquiries') || '[]');
          list.unshift(row);
          localStorage.setItem('pss-inquiries', JSON.stringify(list));
        } catch (err) {}
      }

      function showTicket(row) {
        const tid = row.id || row.trackingId;
        // Always keep a copy locally so Track works even offline
        saveLocal(row);

        if (window.showToast) {
          showToast('Ticket ' + tid + ' created — save this number', 6000);
        }

        // Hide form, show big success card
        contactForm.style.display = 'none';

        let panel = document.getElementById('inquiry-success');
        if (!panel) {
          panel = document.createElement('div');
          panel.id = 'inquiry-success';
          contactForm.parentNode.appendChild(panel);
        }
        panel.hidden = false;
        panel.style.display = 'block';
        panel.className = 'glass-card';
        panel.style.cssText =
          'display:block;margin-top:0;padding:1.75rem 1.5rem;text-align:center;border:2px solid var(--pk-emerald);';
        panel.innerHTML =
          '<div style="width:56px;height:56px;margin:0 auto 1rem;border-radius:50%;background:var(--pk-emerald);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.75rem;font-weight:700">✓</div>' +
          '<h3 style="margin:0 0 0.35rem;color:var(--pk-green);font-size:1.35rem">Inquiry submitted</h3>' +
          '<p style="margin:0 0 1rem;color:var(--text-secondary);font-size:0.95rem">Your ticket number is:</p>' +
          '<div id="inq-ticket-display" style="font-family:Space Grotesk,system-ui,sans-serif;font-size:clamp(1.25rem,4vw,1.75rem);font-weight:700;letter-spacing:0.06em;color:var(--pk-emerald);background:var(--pk-emerald-soft);border:1px dashed var(--pk-emerald);border-radius:0.75rem;padding:0.85rem 1rem;margin:0 auto 1rem;max-width:100%;word-break:break-all">' +
          tid +
          '</div>' +
          '<button type="button" class="btn btn-secondary btn-sm" id="inq-copy-btn" style="margin-bottom:1rem">Copy ticket number</button>' +
          '<p style="font-size:0.9rem;color:var(--text-muted);margin:0 0 1.25rem;line-height:1.5">We will reply to <strong>' +
          (row.email || '') +
          '</strong>' +
          (row.phone ? ' / ' + row.phone : '') +
          '.<br>Use this ticket below in <strong>Track an Inquiry</strong> anytime.</p>' +
          '<div style="display:flex;flex-wrap:wrap;gap:0.5rem;justify-content:center">' +
          '<button type="button" class="btn btn-primary" id="inq-print-btn">Print receipt</button>' +
          '<button type="button" class="btn btn-secondary" id="inq-another-btn">Submit another</button>' +
          '</div>';

        // Pre-fill track box
        const trackId = document.getElementById('inq-lookup-id');
        const trackEm = document.getElementById('inq-lookup-email');
        if (trackId) trackId.value = tid;
        if (trackEm) trackEm.value = row.email || '';

        panel.scrollIntoView({ behavior: 'smooth', block: 'center' });

        const copyBtn = document.getElementById('inq-copy-btn');
        if (copyBtn) {
          copyBtn.addEventListener('click', function () {
            if (navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(tid).then(function () {
                copyBtn.textContent = 'Copied!';
                if (window.showToast) showToast('Ticket number copied');
              });
            } else {
              const ta = document.createElement('textarea');
              ta.value = tid;
              document.body.appendChild(ta);
              ta.select();
              try { document.execCommand('copy'); } catch (err) {}
              document.body.removeChild(ta);
              copyBtn.textContent = 'Copied!';
            }
          });
        }

        const printBtn = document.getElementById('inq-print-btn');
        if (printBtn) {
          printBtn.addEventListener('click', function () {
            const w = window.open('', '_blank', 'width=640,height=800');
            if (!w) return;
            const html =
              typeof window.pssInquiryPrintHTML === 'function'
                ? window.pssInquiryPrintHTML(row)
                : '<html><body><h1>' + tid + '</h1><p>' + (row.name || '') + '</p><script>print()<\\/script></body></html>';
            w.document.write(html);
            w.document.close();
          });
        }

        const anotherBtn = document.getElementById('inq-another-btn');
        if (anotherBtn) {
          anotherBtn.addEventListener('click', function () {
            panel.style.display = 'none';
            panel.hidden = true;
            contactForm.style.display = '';
            contactForm.reset();
            if (submitBtn) {
              submitBtn.disabled = false;
              submitBtn.textContent = 'Send Message';
            }
          });
        }

        // Email school
        try {
          if (window.PSSNotify && window.PSSNotify.notify) {
            window.PSSNotify.notify({
              type: 'inquiry_submitted',
              to: row.email,
              phone: row.phone,
              trackingId: tid,
              name: row.name,
              subject: row.subject,
              message: row.message
            });
          }
        } catch (err) {}
      }

      // Save local first (instant), then cloud
      saveLocal(inquiry);

      (async function () {
        try {
          if (window.PSSCloud) {
            await window.PSSCloud.init();
            if (window.PSSCloud.addInquiry) {
              const saved = await window.PSSCloud.addInquiry(inquiry);
              if (saved && (saved.id || saved.trackingId)) {
                inquiry.id = saved.trackingId || saved.id || inquiry.id;
                inquiry.trackingId = inquiry.id;
              }
            }
          }
        } catch (err) {
          console.warn('inquiry cloud save', err);
        }
        showTicket(inquiry);
      })();
    });
  }


  // ===== Back to Top =====
  const backToTop = document.createElement('button');
  backToTop.className = 'back-to-top';
  backToTop.setAttribute('aria-label', 'Back to top');
  backToTop.innerHTML = '<svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path d="M18 15l-6-6-6 6"/></svg>';
  document.body.appendChild(backToTop);
  window.addEventListener('scroll', () => {
    backToTop.classList.toggle('visible', window.scrollY > 500);
  }, { passive: true });
  backToTop.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  // ===== Mobile menu: close on Escape + outside =====
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const mobileNav = document.getElementById('mobile-nav');
      const menuToggle = document.getElementById('menu-toggle');
      if (mobileNav && mobileNav.classList.contains('open')) {
        mobileNav.classList.remove('open');
        if (menuToggle) menuToggle.setAttribute('aria-expanded', 'false');
      }
      document.querySelectorAll('.modal-overlay.open').forEach(m => {
        m.classList.remove('open');
        document.body.style.overflow = '';
      });
    }
  });

  // ===== Smooth close mobile nav when clicking outside =====
  const mobileNavEl = document.getElementById('mobile-nav');
  if (mobileNavEl) {
    document.addEventListener('click', (e) => {
      if (!mobileNavEl.classList.contains('open')) return;
      const toggle = document.getElementById('menu-toggle');
      if (!mobileNavEl.contains(e.target) && toggle && !toggle.contains(e.target)) {
        mobileNavEl.classList.remove('open');
        if (toggle) toggle.setAttribute('aria-expanded', 'false');
      }
    });
  }

  // ===== Active Nav Link =====
  const path = window.location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.nav-links a, .mobile-nav a').forEach(a => {
    const href = a.getAttribute('href');
    if (href === path || (path === '' && href === 'index.html')) {
      a.classList.add('active');
    }
  });

  // ===== Animate stats on scroll =====
  const stats = document.querySelectorAll('.stat-value[data-count]');
  if (stats.length) {
    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const el = entry.target;
          const target = parseInt(el.dataset.count, 10);
          const suffix = el.dataset.suffix || '';
          let current = 0;
          const step = Math.ceil(target / 40);
          const timer = setInterval(() => {
            current += step;
            if (current >= target) {
              current = target;
              clearInterval(timer);
            }
            el.textContent = current.toLocaleString() + suffix;
          }, 30);
          observer.unobserve(el);
        }
      });
    }, { threshold: 0.5 });
    stats.forEach(s => observer.observe(s));
  }

  // ===== Add to Calendar (.ics) =====
  document.querySelectorAll('[data-ics]').forEach(btn => {
    btn.addEventListener('click', () => {
      const data = JSON.parse(btn.dataset.ics);
      const ics = [
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//Pakistan School Seeb//EN',
        'BEGIN:VEVENT',
        `DTSTART:${data.start}`,
        `DTEND:${data.end}`,
        `SUMMARY:${data.title}`,
        `DESCRIPTION:${data.desc || ''}`,
        `LOCATION:${data.location || 'Pakistan School Seeb'}`,
        'END:VEVENT',
        'END:VCALENDAR'
      ].join('\r\n');
      const blob = new Blob([ics], { type: 'text/calendar' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${data.title.replace(/\s+/g, '-')}.ics`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('Event added to your calendar!');
    });
  });


  // ===== Network directory =====
  const branchInfo = {
    seeb: 'Seeb — our campus in Al Seeb, Muscat. Over 1,300 students, FBISE & Cambridge pathways, KG–Grade 12.',
    muscat: 'Muscat — headquarters of Pakistan Schools Oman; main campus and board administration.',
    sohar: 'Sohar — northern branch serving the Al Batinah community with quality FBISE education.',
    nizwa: 'Nizwa — interior branch in Ad Dakhiliyah, part of the Pakistan Schools Oman family.',
    salalah: 'Salalah — southern Dhofar branch, one of the network’s long-standing campuses.',
    buraimi: 'Buraimi — northwestern branch near the border, serving local expatriate families.',
    musannah: 'Musannah — Al Batinah South branch, connected through shared standards and events.',
    suwaiq: 'Suwaiq — Al Batinah branch of Pakistan School Muscat, connected through shared standards and events.',
    mabelah: 'Mabelah — planned expansion campus to serve growing communities in the Muscat area.'
  };
  const blurb = document.getElementById('branch-blurb');
  function selectBranch(id) {
    document.querySelectorAll('.network-item').forEach(n => {
      n.classList.toggle('is-active', n.dataset.branch === id);
    });
    if (blurb && branchInfo[id]) blurb.textContent = branchInfo[id];
  }
  document.querySelectorAll('.network-item[data-branch]').forEach(n => {
    n.addEventListener('click', () => selectBranch(n.dataset.branch));
    n.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        selectBranch(n.dataset.branch);
      }
    });
  });


  // ===== Cookie / privacy consent (lightweight) =====
  (function cookieBanner() {
    if (localStorage.getItem('pss-cookie-ok')) return;
    const bar = document.createElement('div');
    bar.id = 'pss-cookie-bar';
    bar.setAttribute('role', 'dialog');
    bar.setAttribute('aria-label', 'Cookie notice');
    bar.innerHTML = `
      <div style="max-width:1100px;margin:0 auto;display:flex;flex-wrap:wrap;gap:0.75rem;align-items:center;justify-content:space-between">
        <p style="margin:0;font-size:0.85rem;flex:1;min-width:200px">
          We use essential storage for language, theme, and forms.
          <a href="privacy.html" style="text-decoration:underline">Privacy Policy</a>
        </p>
        <button type="button" id="pss-cookie-ok" class="btn btn-sm btn-primary">Accept</button>
      </div>`;
    bar.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:950;background:var(--bg-secondary);border-top:1px solid var(--border-glass);padding:0.85rem 1rem;box-shadow:0 -4px 24px rgba(0,0,0,0.08)';
    document.body.appendChild(bar);
    document.getElementById('pss-cookie-ok').addEventListener('click', () => {
      localStorage.setItem('pss-cookie-ok', '1');
      bar.remove();
    });
  })();

  function pssInquiryPrintHTML(row) {
    const tid = row.id || row.trackingId || '';
    const logo = window.PSS_PRINT_LOGO || (new URL('assets/school-logo.png', location.href).href);
    const msg = (row.message || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Inquiry ${tid}</title>
      <style>
        body{font-family:system-ui,-apple-system,sans-serif;padding:2rem;color:#0f172a;max-width:640px;margin:0 auto}
        .head{display:flex;align-items:center;gap:1rem;border-bottom:3px solid #01411C;padding-bottom:1rem;margin-bottom:1.25rem}
        .head img{width:64px;height:64px;object-fit:contain}
        h1{margin:0;color:#01411C;font-size:1.25rem}
        .sub{color:#64748b;font-size:0.85rem;margin:0.2rem 0 0}
        .id{font-size:1.5rem;font-weight:700;color:#00A859;margin:1rem 0;letter-spacing:0.04em}
        .row{margin:0.4rem 0;font-size:0.95rem}
        .msg{background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:0.85rem;margin-top:0.5rem;white-space:pre-wrap}
        .foot{margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;font-size:0.8rem;color:#64748b}
        @media print{body{padding:0}}
      </style></head><body>
      <div class="head">
        <img src="${logo}" alt="Pakistan School Seeb">
        <div>
          <h1>Pakistan School Seeb</h1>
          <p class="sub">Inquiry Receipt · Al Seeb, Muscat, Oman</p>
        </div>
      </div>
      <div class="id">${tid}</div>
      <div class="row"><strong>Status:</strong> ${(row.status||'new')}</div>
      <div class="row"><strong>Name:</strong> ${(row.name||'')}</div>
      <div class="row"><strong>Email:</strong> ${(row.email||'')}</div>
      <div class="row"><strong>Phone:</strong> ${(row.phone||'—')}</div>
      <div class="row"><strong>Subject:</strong> ${(row.subject||'General')}</div>
      <div class="row"><strong>Date:</strong> ${row.createdAt ? new Date(row.createdAt).toLocaleString() : ''}</div>
      <div class="row"><strong>Message:</strong><div class="msg">${msg}</div></div>
      ${row.publicNotes ? `<div class="row"><strong>School note:</strong> ${String(row.publicNotes).replace(/</g,'&lt;')}</div>` : ''}
      <div class="foot">
        Building 356, Way 5889, Al Chradi, Al Seeb · +968 2446 4345<br>
        ${window.PSS_SCHOOL_EMAIL || 'principal.seeb@pakistanschool.edu.om'} · Keep this ID to track your inquiry.
      </div>
      <script>window.onload=function(){window.print()}<\/script>
      </body></html>`;
  }
  window.pssInquiryPrintHTML = pssInquiryPrintHTML;

  // ===== Inquiry status lookup (contact page) =====
  (function inquiryLookup() {
    const form = document.getElementById('contact-form');
    if (!form) return;
    let wrap = document.getElementById('inquiry-lookup');
    if (wrap) return;
    wrap = document.createElement('div');
    wrap.id = 'inquiry-lookup';
    wrap.className = 'glass-card';
    wrap.style.cssText = 'margin-top:1.5rem;padding:1.35rem';
    wrap.innerHTML = `
      <h3 style="margin:0 0 0.35rem;font-size:1.1rem">Track an Inquiry</h3>
      <p style="font-size:0.85rem;color:var(--text-muted);margin:0 0 1rem">Enter your Inquiry ID and the email you used. Status updates when staff reply in Admin.</p>
      <div style="display:grid;gap:0.65rem">
        <input type="text" id="inq-lookup-id" class="form-control" placeholder="INQ-XXXX-XXX" autocomplete="off" style="margin:0">
        <input type="email" id="inq-lookup-email" class="form-control" placeholder="Email used on the form" style="margin:0">
        <button type="button" class="btn btn-primary" id="inq-lookup-btn" style="width:100%">Check Status</button>
      </div>
      <div id="inq-lookup-result" style="margin-top:1rem" aria-live="polite"></div>
    `;
    form.parentNode.appendChild(wrap);

        async function findInquiry(id, em) {
      const key = (id || '').trim().toUpperCase();
      const emL = (em || '').toLowerCase();
      const candidates = [];

      function pushMatch(x) {
        if (!x) return;
        if (
          String(x.trackingId || '').toUpperCase() === key ||
          String(x.id || '').toUpperCase() === key
        ) candidates.push(x);
      }
      function bestRow() {
        if (!candidates.length) return null;
        candidates.sort(function (a, b) {
          const ta = Date.parse(a.updatedAt || a.createdAt || 0) || 0;
          const tb = Date.parse(b.updatedAt || b.createdAt || 0) || 0;
          return tb - ta;
        });
        return candidates[0];
      }
      function emailOk(row) {
        if (!emL) return true;
        return (row.email || '').toLowerCase() === emL;
      }

      // 1) Local first — instant
      try {
        const local = JSON.parse(localStorage.getItem('pss-inquiries') || '[]');
        local.forEach(pushMatch);
      } catch (e) {}
      let row = bestRow();
      if (row && emailOk(row)) return { row };
      if (row && !emailOk(row)) {
        // keep checking cloud in case different record
      }

      // 2) Cloud with short timeout (max ~1.2s) — don't hang on "Looking up…"
      try {
        if (window.PSSCloud) {
          const cloudWork = (async function () {
            await window.PSSCloud.init();
            if (window.PSSCloud.getInquiryByTrackingId) {
              pushMatch(await window.PSSCloud.getInquiryByTrackingId(key));
            }
            // Only full list if still empty (slower path)
            if (!candidates.length && window.PSSCloud.listInquiries) {
              const list = await window.PSSCloud.listInquiries();
              (list || []).forEach(pushMatch);
            }
          })();
          await Promise.race([
            cloudWork,
            new Promise(function (resolve) { setTimeout(resolve, 1200); })
          ]);
        }
      } catch (e) { console.warn('findInquiry cloud', e); }

      row = bestRow();
      if (!row) return { error: 'not_found' };
      if (!emailOk(row)) return { error: 'email' };
      return { row };
    }

    document.getElementById('inq-lookup-btn').addEventListener('click', async () => {
      const id = (document.getElementById('inq-lookup-id').value || '').trim().toUpperCase();
      const em = (document.getElementById('inq-lookup-email').value || '').trim().toLowerCase();
      const out = document.getElementById('inq-lookup-result');
      if (!id) { out.innerHTML = '<p style="color:#EF4444">Please enter your Inquiry ID.</p>'; return; }
      if (!em) { out.innerHTML = '<p style="color:#EF4444">Please enter the email used when submitting.</p>'; return; }
      out.innerHTML = '<p class="inq-lookup-wait" style="color:var(--text-muted);font-size:0.9rem">Checking…</p>';
      const t0 = performance.now();
      const res = await findInquiry(id, em);
      // Ensure UI never feels stuck; result paints immediately after resolve
      if (res.error === 'not_found') {
        out.innerHTML = '<p style="color:var(--text-muted)">No inquiry found for <strong>' + id + '</strong>. Check the ID and try again.</p>';
        return;
      }
      if (res.error === 'email') {
        out.innerHTML = '<p style="color:#EF4444">ID found, but email does not match our records.</p>';
        return;
      }
      const row = res.row;
      const st = (row.status || 'new').toLowerCase();
      const labels = {
        new: 'Received',
        open: 'Open',
        in_progress: 'In Progress',
        awaiting_parent: 'Awaiting Parent Reply',
        resolved: 'Resolved',
        closed: 'Closed / Answered'
      };
      const colors = {
        new: '#64748B',
        open: '#6366F1',
        in_progress: '#2563EB',
        awaiting_parent: '#D97706',
        resolved: '#059669',
        closed: '#00A859'
      };
      out.innerHTML = `
        <div style="padding:1.1rem;border-radius:0.85rem;border:1px solid var(--border-glass);background:var(--bg-secondary)">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:0.5rem;flex-wrap:wrap">
            <code style="font-weight:700;color:var(--pk-green)">${id}</code>
            <span style="padding:0.25rem 0.65rem;border-radius:999px;font-size:0.8rem;font-weight:600;background:${colors[st]||'#64748B'}22;color:${colors[st]||'#64748B'}">${labels[st]||st}</span>
          </div>
          <p style="margin:0.75rem 0 0;font-size:0.9rem"><strong>${row.subject || 'General'}</strong></p>
          <p style="margin:0.35rem 0 0;font-size:0.8rem;color:var(--text-muted)">${row.createdAt ? new Date(row.createdAt).toLocaleString() : ''}</p>
          ${row.publicNotes ? '<div style="margin-top:0.75rem;padding:0.75rem;background:var(--pk-emerald-soft);border-radius:0.5rem;font-size:0.9rem"><strong>Reply from school:</strong><br>' + row.publicNotes + '</div>' : '<p style="margin-top:0.75rem;font-size:0.85rem;color:var(--text-muted)">No public reply yet. Staff will update this when they respond.</p>'}
          
          ${(Array.isArray(row.statusHistory) && row.statusHistory.length) ? (
            '<div style="margin-top:0.85rem"><strong style="font-size:0.8rem;color:var(--text-muted)">Status timeline</strong><ul style="margin:0.4rem 0 0;padding-left:1.1rem;font-size:0.85rem;line-height:1.5">' +
            row.statusHistory.map(function(h){
              const lab = labels[h.status] || h.status;
              const when = h.at ? new Date(h.at).toLocaleString() : '';
              return '<li><strong>' + lab + '</strong> · ' + when + (h.note ? ' — ' + h.note : '') + '</li>';
            }).join('') + '</ul></div>'
          ) : ''}
          <button type="button" class="btn btn-sm btn-secondary" style="margin-top:0.85rem" id="inq-lookup-print">Print receipt</button>
        </div>`;
      document.getElementById('inq-lookup-print')?.addEventListener('click', () => {
        const w = window.open('', '_blank', 'width=640,height=800');
        if (!w) return;
        w.document.write(pssInquiryPrintHTML(row));
        w.document.close();
      });
    });
  })();

})();